import{_ as e,o as a,c as r,an as i}from"./chunks/framework.DTzCKmGP.js";const s="/BVDOutbreakSize/v1.8/assets/rt.BBLhrHq2.png",n="/BVDOutbreakSize/v1.8/assets/infections.BYaW22Sz.png",d="/BVDOutbreakSize/v1.8/assets/reported_cases.T9yzbzNQ.png",o="/BVDOutbreakSize/v1.8/assets/rt_streams.v6wc_ixT.png",b=JSON.parse('{"title":"Summary dashboard","description":"","frontmatter":{},"headers":[],"relativePath":"summary.md","filePath":"summary.md","lastUpdated":null}'),l={name:"summary.md"};function h(g,t,m,u,p,y){return a(),r("div",null,[...t[0]||(t[0]=[i('<h1 id="Summary-dashboard" tabindex="-1">Summary dashboard <a class="header-anchor" href="#Summary-dashboard" aria-label="Permalink to &quot;Summary dashboard {#Summary-dashboard}&quot;">​</a></h1><p>A one-page overview of the headline results for readers with limited time. Every number, table and figure on this page is produced by the same model fit as the full <a href="./analysis">Analysis</a> and refreshes whenever the data updates. See the <a href="./analysis">Analysis</a> page for the methods, assumptions and supporting detail behind each result, and the <a href="./sensitivity">Sensitivity</a> page for the forecast validation, the outbreak size implied by each data stream, the comparisons with McCabe et al. and Chamla et al., and the delay and molecular-clock sensitivity analyses.</p><p><strong>Data as of:</strong> 2026-07-06</p><h2 id="Headline-estimates" tabindex="-1">Headline estimates <a class="header-anchor" href="#Headline-estimates" aria-label="Permalink to &quot;Headline estimates {#Headline-estimates}&quot;">​</a></h2><ul><li><p><strong>Cumulative infections:</strong> the outbreak is estimated to have caused 30% 4174–4811, 60% 3835–5269, 90% 3358–6377 infections to date, reported and unreported.</p></li><li><p>Against the 1708 laboratory-confirmed cases by the cut-off that is roughly 2.0–3.7× as many infections, so confirmed cases are estimated to capture only a small share of the outbreak.</p></li><li><p><strong>Outbreak start and age:</strong> the outbreak is estimated to have begun on a start date of 30% 2026-02-26–2026-03-07, 60% 2026-02-21–2026-03-12, 90% 2026-02-11–2026-03-19, an elapsed age to the cut-off of 30% 121–130, 60% 116–135, 90% 109–145 days.</p></li><li><p><strong>Growth rate and doubling time:</strong> the initial growth rate is estimated to have been 30% 0.035–0.039, 60% 0.033–0.042, 90% 0.029–0.047 per day, an initial doubling time of 30% 17.7–19.9, 60% 16.5–21.3, 90% 14.7–24.1 days. The latest growth rate is estimated to be 30% 0.016–0.033, 60% 0.005–0.041, 90% -0.019–0.058 per day, a latest doubling time of 30% 17.0–27.1, 60% 12.0–42.9, 90% -95.8–143.4 days.</p></li><li><p><strong>Reproduction number:</strong> the initial reproduction number is estimated to have been 30% 1.47–1.67, 60% 1.37–1.82, 90% 1.25–2.13 and the latest to be 30% 1.21–1.53, 60% 1.06–1.71, 90% 0.82–2.2.</p></li><li><p><strong>Case-fatality ratio:</strong> the case-fatality ratio is estimated to be 30% 0.4–0.46, 60% 0.37–0.49, 90% 0.32–0.56.</p></li><li><p><strong>Shift from priors:</strong> how far the data has moved each estimate from its prior, in prior interquartile ranges, where a value of one means the posterior median sits one prior interquartile range from the prior median, zero means unchanged, and the sign gives the direction. The fit moves the cumulative infection count by 0.04, the outbreak age by -0.47 and the doubling time by 0.03; the largest move is in the outbreak age.</p></li></ul><h3 id="Outbreak-size-and-timing" tabindex="-1">Outbreak size and timing <a class="header-anchor" href="#Outbreak-size-and-timing" aria-label="Permalink to &quot;Outbreak size and timing {#Outbreak-size-and-timing}&quot;">​</a></h3><table tabindex="0"><thead><tr><th style="text-align:right;">Quantity</th><th style="text-align:right;">Lower 90%</th><th style="text-align:right;">Lower 60%</th><th style="text-align:right;">Lower 30%</th><th style="text-align:right;">Upper 30%</th><th style="text-align:right;">Upper 60%</th><th style="text-align:right;">Upper 90%</th></tr></thead><tbody><tr><td style="text-align:right;">Cumulative infections</td><td style="text-align:right;">3358</td><td style="text-align:right;">3835</td><td style="text-align:right;">4174</td><td style="text-align:right;">4811</td><td style="text-align:right;">5269</td><td style="text-align:right;">6377</td></tr><tr><td style="text-align:right;">Outbreak age (days)</td><td style="text-align:right;">109</td><td style="text-align:right;">116</td><td style="text-align:right;">121</td><td style="text-align:right;">130</td><td style="text-align:right;">135</td><td style="text-align:right;">145</td></tr></tbody></table><h3 id="Growth-and-severity" tabindex="-1">Growth and severity <a class="header-anchor" href="#Growth-and-severity" aria-label="Permalink to &quot;Growth and severity {#Growth-and-severity}&quot;">​</a></h3><table tabindex="0"><thead><tr><th style="text-align:right;">Quantity</th><th style="text-align:right;">Lower 90%</th><th style="text-align:right;">Lower 60%</th><th style="text-align:right;">Lower 30%</th><th style="text-align:right;">Upper 30%</th><th style="text-align:right;">Upper 60%</th><th style="text-align:right;">Upper 90%</th></tr></thead><tbody><tr><td style="text-align:right;">Initial reproduction number</td><td style="text-align:right;">1.25</td><td style="text-align:right;">1.37</td><td style="text-align:right;">1.47</td><td style="text-align:right;">1.67</td><td style="text-align:right;">1.82</td><td style="text-align:right;">2.13</td></tr><tr><td style="text-align:right;">Latest reproduction number</td><td style="text-align:right;">0.82</td><td style="text-align:right;">1.06</td><td style="text-align:right;">1.21</td><td style="text-align:right;">1.53</td><td style="text-align:right;">1.71</td><td style="text-align:right;">2.2</td></tr><tr><td style="text-align:right;">Latest growth rate (per day)</td><td style="text-align:right;">-0.02</td><td style="text-align:right;">0</td><td style="text-align:right;">0.02</td><td style="text-align:right;">0.03</td><td style="text-align:right;">0.04</td><td style="text-align:right;">0.06</td></tr><tr><td style="text-align:right;">Latest doubling time (days)</td><td style="text-align:right;">-95.75</td><td style="text-align:right;">12.02</td><td style="text-align:right;">16.96</td><td style="text-align:right;">27.05</td><td style="text-align:right;">42.91</td><td style="text-align:right;">143.36</td></tr><tr><td style="text-align:right;">Case-fatality ratio</td><td style="text-align:right;">0.32</td><td style="text-align:right;">0.37</td><td style="text-align:right;">0.4</td><td style="text-align:right;">0.46</td><td style="text-align:right;">0.49</td><td style="text-align:right;">0.56</td></tr></tbody></table><p>All intervals are equal-tailed 30%, 60% and 90% credible intervals from the joint posterior.</p><h2 id="Estimated-reproduction-number" tabindex="-1">Estimated reproduction number <a class="header-anchor" href="#Estimated-reproduction-number" aria-label="Permalink to &quot;Estimated reproduction number {#Estimated-reproduction-number}&quot;">​</a></h2><p>The time-varying reproduction number R(t), the average number of further infections caused by each infection. A value above one means the outbreak is growing.</p><p><img src="'+s+'" alt=""></p><h2 id="Infections-over-time" tabindex="-1">Infections over time <a class="header-anchor" href="#Infections-over-time" aria-label="Permalink to &quot;Infections over time {#Infections-over-time}&quot;">​</a></h2><p>Modelled cumulative infections, symptom onsets and deaths. These are the underlying outbreak, upstream of the testing and reporting that produce the observed counts, so they are larger than the reported cases.</p><p><img src="'+n+'" alt=""></p><h2 id="Reported-cases:-model-versus-observed" tabindex="-1">Reported cases: model versus observed <a class="header-anchor" href="#Reported-cases:-model-versus-observed" aria-label="Permalink to &quot;Reported cases: model versus observed {#Reported-cases:-model-versus-observed}&quot;">​</a></h2><p>Modelled reported cases against the observed reported cases over time, a check that the fit reproduces what was seen on the ground.</p><p><img src="'+d+'" alt=""></p><h2 id="Reproduction-number-by-data-stream" tabindex="-1">Reproduction number by data stream <a class="header-anchor" href="#Reproduction-number-by-data-stream" aria-label="Permalink to &quot;Reproduction number by data stream {#Reproduction-number-by-data-stream}&quot;">​</a></h2><p>The reproduction number each data stream implies on its own, fitted to that stream alone. Agreement between the streams supports the joint estimate; disagreement shows where they pull in different directions.</p><p><img src="'+o+'" alt=""></p><hr><p>For the full results, methods and code see the <a href="./analysis">Analysis</a> page and the <a href="https://github.com/epiforecasts/BVDOutbreakSize" target="_blank" rel="noreferrer">epiforecasts/BVDOutbreakSize</a> repository.</p>',24)])])}const f=e(l,[["render",h]]);export{b as __pageData,f as default};
